'use strict';
// A first-visit path that never transfers funds or starts a simulation automatically.
if(!demo.plan&&demo.portfolio.length===2&&demo.portfolio.includes(279342)&&demo.portfolio.includes(150357))demo.portfolio=[371815,127227];
const shownPhotoStations=[371815,127227,147079];
function renderPhotoExplorer(){let section=$('#photo-explorer');if(!section){section=document.createElement('section');section.id='photo-explorer';section.className='photo-explorer';$('#map-section').before(section)}section.hidden=tab!=='dashboard';const rows=shownPhotoStations.map(id=>stations.find(s=>s.id===id)).filter(s=>s&&stationPhoto(s));if(!rows.length){section.hidden=true;return}section.innerHTML=`<div class="explorer-heading"><div><h2>Explore real locations</h2><p>Choose a station to see its details and try an allocation.</p></div><button class="text-button" data-action="explore-map">Open map ${icon('arrow')}</button></div><div class="location-rail" aria-label="Featured station locations">${rows.map(s=>{const photo=stationPhoto(s);return `<button class="location-card" data-explore-station="${s.id}" aria-label="View ${escapeHtml(s.name)}"><img src="${escapeHtml(photo.path)}" alt="${escapeHtml(photo.alt)}" width="1280" height="960" loading="lazy"><span class="location-card-body"><strong>${escapeHtml(s.city)}, ${s.state}</strong><span>${escapeHtml(s.name.replace(/\s*\([^)]*\)\s*$/,''))}</span><small>${s.ports} DC ports · ${s.maxKw||'—'} kW max ${icon('arrow')}</small></span></button>`}).join('')}</div>`}
actions['explore-map']=()=>{tab='map';renderClientTab();setTimeout(()=>actions['fit-map'](),150);window.scrollTo({top:0,behavior:'instant'})};
actions['demo-guide']=()=>openModal(`<h2>Try the complete demo</h2><p>Explore the product with sample funds. No payment is collected.</p><ol class="demo-guide-list"><li><strong>Choose a real location</strong><span>Open a station, review its photo and address, then select it for a demo investment.</span><button class="button secondary" data-action="guide-map">Explore stations ${icon('map')}</button></li><li><strong>Build a demo plan</strong><span>Compare 1, 3, 5 or 10 reference stations. The daily rate applies once to the total capital.</span><button class="button secondary" data-action="tariffs">Compare plans ${icon('zap')}</button></li><li><strong>Try a daily accrual</strong><span>After applying a plan, use “Simulate day” to record a test event. View the balance, history and printable agreement.</span></li></ol><div class="modal-note">The Staff console lets you edit the client profile and plan, approve demo requests and reply to messages. Demo data stays in this browser; other visitors start with their own sample account.</div><button class="button primary" data-action="guide-manager">Explore manager workspace ${icon('users')}</button>`);
actions['guide-map']=()=>{$('#modal').close();actions['explore-map']()};
actions['guide-manager']=()=>{$('#modal').close();setRole('admin');adminTab='overview';renderAdmin()};
const planBarBeforeGuide=renderPlanBar;
renderPlanBar=function(){planBarBeforeGuide();let guide=$('#demo-walkthrough');if(!guide){guide=document.createElement('div');guide.id='demo-walkthrough';guide.className='demo-walkthrough';$('#plan-shortcut').after(guide)}guide.hidden=tab!=='dashboard';guide.innerHTML=`<span>${icon('shield')} ${demo.plan?'Demo plan ready. Try one day and review your history.':'Choose a station. Pick a plan. Try one demo day.'}</span><button data-action="demo-guide">How it works ${icon('arrow')}</button>`;renderPhotoExplorer()};
const photoBeforeExplorer=updateStationPhoto;
updateStationPhoto=function(s){photoBeforeExplorer(s);const image=$('.station-photo img');if(image){image.loading='lazy';image.decoding='async'}renderPhotoExplorer()};
const navigationBeforeMobile=renderNav;
renderNav=function(){navigationBeforeMobile();const active=$('.main-nav .active');if(active)active.setAttribute('aria-current','page');const skip=$('#skip-content');if(skip)skip.href=role==='admin'?'#admin-view':'#client-view';const url=new URL(location);url.searchParams.set('view',role);url.searchParams.set('tab',role==='admin'?adminTab:tab);history.replaceState({},'',url)};
const clientTabBeforeMobile=renderClientTab;
renderClientTab=function(){clientTabBeforeMobile();renderPhotoExplorer();const heading=$('#client-page-title');if(heading)heading.textContent=({dashboard:'Investor overview',map:'Charging station map',assets:'Your reference stations',documents:'Documents and support',tariffs:'Daily demo plans'})[tab]||'Investor portal'};
const roleBeforeMobile=setRole;
let routeRestored=false;
setRole=function(next){if(!routeRestored){const t=new URL(location).searchParams.get('tab');if(next==='admin'&&['overview','clients','requests','stations','tariffs','plan'].includes(t))adminTab=t;if(next!=='admin'&&['dashboard','map','assets','documents','tariffs'].includes(t))tab=t;routeRestored=true}roleBeforeMobile(next)};
const openModalBeforeMobile=openModal;
openModal=function(html){openModalBeforeMobile(html);const heading=$('#modal-content h2');if(heading){heading.id='dialog-title';$('#modal').setAttribute('aria-labelledby','dialog-title')}$('#modal').scrollTop=0};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.exploreStation){selectStation(b.dataset.exploreStation);actions.station()}if(b.dataset.tab||b.dataset.managerView)window.scrollTo({top:0,behavior:'instant'})});
document.body.insertAdjacentHTML('afterbegin','<a id="skip-content" class="skip-link" href="#client-view">Skip to content</a>');
$('#client-view').insertAdjacentHTML('afterbegin','<h1 id="client-page-title" class="sr-only">Investor overview</h1>');
$('#client-view').setAttribute('tabindex','-1');$('#admin-view').setAttribute('tabindex','-1');
$('#modal').addEventListener('close',()=>{if(document.activeElement===$('#skip-content'))$(role==='admin'?'#admin-view':'#client-view').focus({preventScroll:true})});
$('.prototype-bar>span').insertAdjacentHTML('beforeend','<button class="demo-help" data-action="demo-guide" aria-label="How to use the demo">?</button>');
renderPhotoExplorer();
